class ServiceProxy:
    def __init__(self, service: ServiceApi, metrics: Metrics) -> None:
        self._service = service
        self._metrics = metrics
    def __getattr__(self, name):                    # forwards everything else
        return getattr(self._service, name)
    def call(self, request: Request) -> Response:   # control lives here
        started = time.perf_counter()
        try:
            return self._service.call(request)      # same contract
        finally:
            self._metrics.observe("call", time.perf_counter() - started)

