class PolicyInterceptor(grpc.ServerInterceptor):
    def intercept_service(self, continuation, details):
        handler = continuation(details)                  # the real service
        def wrap(request, context):                      # policy: measure
            started = time.perf_counter()
            try:
                return handler.unary_unary(request, context)
            finally:
                metrics.observe(details.method, time.perf_counter() - started)
        return grpc.unary_unary_rpc_method_handler(
            wrap, request_deserializer=handler.request_deserializer,
            response_serializer=handler.response_serializer)
